/* ==========================================================================
   GLASSMORPHISM DASHBOARD STYLESHEET
   Theme Variations & Glass Core Tokens
   ========================================================================== */
:root {
  /* Default Theme: Cyberpunk Dark Glass */
  --bg-base: #080b14;
  --orb-1: #00f2fe;
  --orb-2: #7928ca;
  --orb-3: #ff007f;
  --glass-bg: rgba(15, 23, 42, 0.55);
  --glass-border: rgba(0, 242, 254, 0.22);
  --glass-border-hover: rgba(0, 242, 254, 0.6);
  --glass-shadow: 0 12px 40px 0 rgba(0, 242, 254, 0.15);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent: #00f2fe;
  --accent-secondary: #ff007f;
  --accent-glow: rgba(0, 242, 254, 0.4);
  --card-gradient: linear-gradient(135deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02));
  --backdrop-blur: blur(20px);
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

/* Theme 1: Cyberpunk Glass */
