/* ==========================================================================
   Draggable KPI Metric Cards Grid
   ========================================================================== */
.draggable-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
}

.kpi-card {
  padding: 20px 22px;
  cursor: grab;
  position: relative;
}

.kpi-card:active {
  cursor: grabbing;
}

.kpi-card.dragging {
  opacity: 0.4;
  border-dash: 2px dashed var(--accent);
  transform: scale(0.98);
}

.kpi-card.drag-over {
  border-color: var(--accent);
  box-shadow: 0 0 20px var(--accent-glow);
}

.card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.kpi-icon-box {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid var(--glass-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
}

