/* ==========================================================================
   Interactive Main SVG Chart Widget
   ========================================================================== */
.chart-panel {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.chart-title-box h2 {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-main);
}

.chart-title-box p {
  font-size: 12px;
  color: var(--text-muted);
}

.chart-legend {
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 12px;
  color: var(--text-muted);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

/* SVG Interactive Canvas Container */
.svg-chart-container {
  position: relative;
  width: 100%;
  height: 280px;
}

.main-svg-chart {
  width: 100%;
  height: 100%;
  overflow: visible;
}

