(function () {
  window.DesignExampleInteractions = {
    installModal(id, state) {
      window.openModal = () => document.getElementById(id).classList.add(state);
      window.closeModal = () => document.getElementById(id).classList.remove(state);
    },
    closeDropdowns() {
      document.querySelectorAll('.dropdown').forEach(element => element.classList.remove('open'));
    },
    dragAfter(container, x) {
      const candidates = [...container.querySelectorAll('.kpi-card:not(.dragging)')];
      return candidates.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = x - box.left - box.width / 2;
        return offset < 0 && offset > closest.offset ? { offset, element: child } : closest;
      }, { offset: Number.NEGATIVE_INFINITY }).element;
    }
  };
})();

/* ==========================================================================
   Theme Switcher & Glass Accent Handlers
   ========================================================================== */
function switchTheme(themeName) {
  document.body.setAttribute('data-theme', themeName);

  document.querySelectorAll('.switcher-btn').forEach(btn => {
    btn.classList.remove('active');
    if (btn.getAttribute('data-theme-target') === themeName) {
      btn.classList.add('active');
    }
  });
}

/* ==========================================================================
   Accordion Menu Toggle
   ========================================================================== */
function toggleAccordion(itemId) {
  const targetItem = document.getElementById(itemId);
  const isOpen = targetItem.classList.contains('open');

  document.querySelectorAll('.accordion-item').forEach(item => {
    item.classList.remove('open');
  });

  if (!isOpen) {
    targetItem.classList.add('open');
  }
}

/* ==========================================================================
   Count-Up Number Animation
   ========================================================================== */
function animateValue(obj, start, end, duration, prefix = '', suffix = '', decimals = 0) {
  let startTimestamp = null;
  const step = (timestamp) => {
    if (!startTimestamp) startTimestamp = timestamp;
    const progress = Math.min((timestamp - startTimestamp) / duration, 1);
    const current = start + progress * (end - start);

    let formatted = decimals > 0 ? current.toFixed(decimals) : Math.floor(current).toLocaleString();
    obj.innerHTML = `${prefix}${formatted}${suffix}`;

    if (progress < 1) {
      window.requestAnimationFrame(step);
    }
  };
  window.requestAnimationFrame(step);
}

